begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1705 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:243505546e6def658c68be08' and md5(to_jsonb(t)::text)='41a7e6336f1b8adc7d09b9a32ad1a190')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:243505546e6def658c68be08';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_038a74766038eaf3$"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas."$text_038a74766038eaf3$::jsonb,true),'{features}',$text_3e786f0a1bd7f240$[{"id":"consume-crystal","kind":"other","name":"Consumir cristal: elegir un efecto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas.\n\nElegir recuperación de espacio de nivel 1 o 2d6 PG temporales (con 1d4 de curación solo en el templo). No aplicar ambas opciones. Conservar corrupción, destrucción y uso de tres fragmentos en mecanismos.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_3e786f0a1bd7f240$::jsonb,true),'{rules,definition,description}',$text_0cd83eeefae6555b$[{"id":"campaign-text-0","text":"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_0cd83eeefae6555b$::jsonb,true),'{rules,personalDescription}',$text_a7dfd88bd47b9ed4$"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\n<strong>Mecánica</strong>\n<strong>Usar:</strong> acción. El fragmento se consume.\n\n<strong>Efecto (elige uno)</strong>\n• <strong>Recarga menor:</strong> restaura una ranura de conjuro de <u>1.er nivel</u> (no rituales).\n• <strong>Pulso vital:</strong> otorga <u>2d6</u> puntos de golpe temporales a una criatura y cura <u>1d4</u> adicionales si se usa dentro del templo.\n\n<strong>Corruptibilidad</strong>\n• <u>+1 MC</u> si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\n<strong>Identificación</strong>\n<em>Arcana CD 12</em> o <em>Identificar</em>.\n\n<strong>Destrucción</strong>\nAplastarlo (<em>Fuerza CD 10</em>) libera un pulso de <u>1d6</u> de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\n<strong>Uso en puzzles o artefactos</strong>\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas."$text_a7dfd88bd47b9ed4$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:243505546e6def658c68be08';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:7464ea9038f8df5a37722aca' and md5(to_jsonb(t)::text)='5e2237d53cc625029a4373e1abde359e')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:7464ea9038f8df5a37722aca';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_2665a32b1b3ad0b3$[{"id":"intelligence-bonus","kind":"passive","name":"Inteligencia +1","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras estés sintonizado con Sombra del Segador y el objeto esté en contacto con tu cuerpo, tu puntuación de Inteligencia aumenta en 1. Marca de la Cercanía tiene un uso y recupera el uso gastado al amanecer. Los demás poderes, requisitos y contrapartidas conservan sus reglas descritas.\n\nDuración: Mientras se cumplan equipo y sintonización..","showInActions":false},{"id":"veil-of-penumbra","kind":"other","name":"Velo de Penumbra","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Velo de Penumbra\n\nMientras estés vinculado al objeto, la luz en un radio de 3 metros (10 pies) se atenúa ligeramente. La luz brillante pasa a ser luz tenue, y la luz tenue pasa a ser oscuridad no mágica (las criaturas con visión en la oscuridad ven esta área como luz tenue). Las criaturas que dependen de la vista tienen desventaja en las tiradas de Percepción para detectar al portador si permanece inmóvil.\n\nLuz brillante pasa a tenue y luz tenue a oscuridad no mágica a 10 pies; conservar la interacción con visión en la oscuridad descrita por el objeto.\n\nDuración: Mientras se cumplan equipo y sintonización..\n\nAlcance: Radio de 10 pies (3 m).","showInActions":false},{"id":"nearness-mark","kind":"other","name":"Marca de la Cercanía","uses":null,"order":2,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d6"}],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Marca de la Cercanía (1/día)\n\nComo acción adicional, puedes marcar a una criatura que veas a 9 metros (30 pies). Durante 1 minuto:\n\nLa primera vez que el objetivo caiga por debajo de la mitad de sus puntos de golpe, recibe 2d6 de daño necrótico adicional.\n\nEl objetivo no puede beneficiarse de puntos de golpe temporales durante este efecto.\n\nEste efecto termina antes si pierdes la concentración (como si concentraras un conjuro, CD 10 o la mitad del daño recibido, lo que sea mayor).\n\nMientras estés sintonizado con Sombra del Segador y el objeto esté en contacto con tu cuerpo, tu puntuación de Inteligencia aumenta en 1. Marca de la Cercanía tiene un uso y recupera el uso gastado al amanecer. Los demás poderes, requisitos y contrapartidas conservan sus reglas descritas.\n\nEl objetivo no puede beneficiarse de PG temporales mientras dure la marca; termina al perder la concentración o al cumplirse 1 minuto.\n\nDuración: Hasta 1 minuto.\n\nAlcance: 30 pies (9 m).\n\nConcentración: sí.\n\nCoste: 1 Marca de la Cercanía.","showInActions":false},{"id":"lingering-presence","kind":"other","name":"Presencia Persistente","uses":null,"order":3,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Presencia Persistente\n\nCuando una criatura muere a menos de 4,5 metros (15 pies) de ti, obtienes ventaja en tu siguiente tirada de ataque o tirada de salvación antes del final de tu siguiente turno. Si no usas este beneficio, en su lugar tienes desventaja en tu siguiente tirada de salvación de Sabiduría (el “peso” persiste).\n\nVentaja en el siguiente ataque o salvación antes del final del siguiente turno; si no se aprovecha, desventaja en la siguiente salvación de Sabiduría.\n\nDuración: Beneficio hasta el final de tu siguiente turno; la contrapartida se resuelve como indica el texto..\n\nAlcance: 15 pies (4,5 m).","showInActions":false},{"id":"whisper-of-finality","kind":"other","name":"Susurro de Finalidad","uses":null,"order":4,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Susurro de Finalidad (desventaja)\n\nCada vez que uses Marca de la Cercanía, realiza una tirada de salvación de Sabiduría CD 12. Si fallas, quedas afectado por un fatalismo latente hasta tu próximo descanso largo:\n\nTienes desventaja en las tiradas de salvación contra la muerte.\n\nNo puedes acercarte voluntariamente a una criatura con todos sus puntos de golpe a menos que superes una prueba de Sabiduría CD 10.\n\nCada uso de la marca exige Sabiduría CD 12. Fallar también impide acercarse voluntariamente a criaturas con todos sus PG salvo prueba de Sabiduría CD 10. La recuperación al amanecer del uso de la marca no elimina esta penalización.\n\nDuración: Si fallas la salvación, hasta tu próximo descanso largo..","showInActions":false}]$text_2665a32b1b3ad0b3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:7464ea9038f8df5a37722aca';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:7600b9e4640022d731c55428' and md5(to_jsonb(t)::text)='3ec97dec9b2991ec546163bca217a4a7')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:7600b9e4640022d731c55428';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_e09c41a0993ee9c2$"Una capa elegante y sorprendentemente liviana, tejida con hilos que parecen captar la luz y devolverla como un brillo sutil en el borde de la tela. Cuando se la lleva puesta, su caída y su presencia amplifican la intención del portador: cada palabra suena un poco más convincente, cada gesto un poco más seguro.\n\nEfecto\nMientras estés vinculado a esta capa, tu puntuación de Carisma aumenta en +1, hasta un máximo de 20.\n\nImpacto en conjuros\nEste aumento de Carisma también mejora tu CD de salvación de conjuros y tus tiradas de ataque de conjuro si tu clase lanza conjuros usando Carisma.\n\nEncaja especialmente con: pactos feéricos, seducción, dominio social y manipulación sutil."$text_e09c41a0993ee9c2$::jsonb,true),'{features}',$text_7b0c35e6dee571ba$[{"id":"legacy-bonus-0","kind":"passive","name":"CHA","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Carisma +1 (máx. 20).","showInActions":false},{"id":"charisma-bonus","kind":"passive","name":"Carisma +1","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Una capa elegante y sorprendentemente liviana, tejida con hilos que parecen captar la luz y devolverla como un brillo sutil en el borde de la tela. Cuando se la lleva puesta, su caída y su presencia amplifican la intención del portador: cada palabra suena un poco más convincente, cada gesto un poco más seguro.\n\nEfecto\nMientras estés vinculado a esta capa, tu puntuación de Carisma aumenta en +1, hasta un máximo de 20.\n\nImpacto en conjuros\nEste aumento de Carisma también mejora tu CD de salvación de conjuros y tus tiradas de ataque de conjuro si tu clase lanza conjuros usando Carisma.\n\nEncaja especialmente con: pactos feéricos, seducción, dominio social y manipulación sutil.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_7b0c35e6dee571ba$::jsonb,true),'{rules,definition,description}',$text_a2bf17b2daf6b053$[{"id":"campaign-text-0","text":"Una capa elegante y sorprendentemente liviana, tejida con hilos que parecen captar la luz y devolverla como un brillo sutil en el borde de la tela. Cuando se la lleva puesta, su caída y su presencia amplifican la intención del portador: cada palabra suena un poco más convincente, cada gesto un poco más seguro.\n\nEfecto\nMientras estés vinculado a esta capa, tu puntuación de Carisma aumenta en +1, hasta un máximo de 20.\n\nImpacto en conjuros\nEste aumento de Carisma también mejora tu CD de salvación de conjuros y tus tiradas de ataque de conjuro si tu clase lanza conjuros usando Carisma.\n\nEncaja especialmente con: pactos feéricos, seducción, dominio social y manipulación sutil.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_a2bf17b2daf6b053$::jsonb,true),'{rules,personalDescription}',$text_e72aac44c161504a$"Una capa elegante y sorprendentemente liviana, tejida con hilos que parecen captar la luz y devolverla como un brillo sutil en el borde de la tela. Cuando se la lleva puesta, su caída y su presencia amplifican la intención del portador: cada palabra suena un poco más convincente, cada gesto un poco más seguro.\n\n<strong>Efecto</strong>\nMientras estés vinculado a esta capa, tu puntuación de <strong>Carisma</strong> aumenta en <strong>+1</strong>, hasta un máximo de <strong>20</strong>.\n\n<strong>Impacto en conjuros</strong>\nEste aumento de Carisma también mejora tu <em>CD de salvación de conjuros</em> y tus <em>tiradas de ataque de conjuro</em> si tu clase lanza conjuros usando Carisma.\n\n<em>Encaja especialmente con:</em> pactos feéricos, seducción, dominio social y manipulación sutil."$text_e72aac44c161504a$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:7600b9e4640022d731c55428';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:99f2c411caadf247bd3d459a' and md5(to_jsonb(t)::text)='32d723f032162655f814cd06ed5f5000')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:99f2c411caadf247bd3d459a';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_1f6ade25871e7370$"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro Armadura de mago sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera 1d6+1 cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes un 1 en un d20, la varita colapsa y se desintegra en polvo inerte."$text_1f6ade25871e7370$::jsonb,true),'{features}',$text_d04fcefb0f1fc219$[{"id":"mage-armor","kind":"other","name":"Armadura de mago","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro Armadura de mago sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera 1d6+1 cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes un 1 en un d20, la varita colapsa y se desintegra en polvo inerte.\n\nAl gastar la última carga: tirar 1d20; con un 1 la varita se destruye. Conservar este procedimiento junto al lanzamiento.\n\nDuración: 8 horas.\n\nCoste: 1 cargas.","showInActions":false}]$text_d04fcefb0f1fc219$::jsonb,true),'{rules,definition,description}',$text_47a68dad3bab2250$[{"id":"campaign-text-0","text":"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro Armadura de mago sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera 1d6+1 cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes un 1 en un d20, la varita colapsa y se desintegra en polvo inerte.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_47a68dad3bab2250$::jsonb,true),'{rules,personalDescription}',$text_feeda7894407784e$"Esta varita delgada está tallada en madera pulida y reforzada con finas incrustaciones arcanas que recorren su superficie como un entramado geométrico. \n Fue diseñada para proyectar una defensa estable y eficiente, encapsulando un conjuro defensivo en una forma controlada y repetible.\n\nLa varita posee 3 cargas, y mientras la sostienes puedes usar una acción para gastar 1 carga y lanzar el conjuro <u>Armadura de mago</u> sin necesidad de componentes materiales. \n Cada amanecer, la varita recupera <u>1d6+1</u> cargas gastadas, como si reordenara lentamente su estructura mágica interna.\n\nSin embargo, forzarla hasta consumir su última carga puede quebrar ese equilibrio: si al gastar la última carga obtienes <u>un 1 en un d20</u>, la varita colapsa y se desintegra en polvo inerte."$text_feeda7894407784e$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:99f2c411caadf247bd3d459a';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:ad2b2b095ece73a10323c150' and md5(to_jsonb(t)::text)='d412c74d9e0758ceafc4362d6caa9bcc')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:ad2b2b095ece73a10323c150';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{rules,personalDescription}',$text_53221947b83782f3$"Esta capa está tejida con hilos oscuros y resistentes, en cuyo forro interior se inscriben antiguas runas arcanas apenas visibles cuando la tela descansa. \n Al portarla, el usuario siente un leve pulso mágico, como si la prenda almacenara fragmentos de energía latente. \n Mientras se viste esta capa, el portador obtiene una ranura adicional de conjuro de nivel 1."$text_53221947b83782f3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:ad2b2b095ece73a10323c150';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:bc5bf83aa5545f2bc45f837c' and md5(to_jsonb(t)::text)='6daaac8af434fe9a173fd05af406a343')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:bc5bf83aa5545f2bc45f837c';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_a1570cd70d2f5f70$"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos."$text_a1570cd70d2f5f70$::jsonb,true),'{features}',$text_af3cf1a757f09185$[{"id":"reserve-crystal","kind":"other","name":"Reserva arcana y descarga","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos.\n\nTres opciones de gasto 1/2/3; registrar por separado la corrupción MC, la ventana de 10 minutos, identificación, destrucción y uso en mecanismos. No sustituir la descarga por un conjuro oficial ni descartar sus costes de campaña.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_af3cf1a757f09185$::jsonb,true),'{rules,definition,description}',$text_5b8325390af9ea64$[{"id":"campaign-text-0","text":"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_5b8325390af9ea64$::jsonb,true),'{rules,personalDescription}',$text_ab91e77706d4cd95$"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\n<strong>Mecánica</strong>\n<strong>Cargas:</strong> 3. Recupera <u>1d3</u> cargas al amanecer.\n\n<strong>Usos</strong>\n• <strong>1 carga:</strong> lanzar un conjuro de <u>1.er nivel</u> sin gastar ranura.\n• <strong>2 cargas:</strong> lanzar un conjuro de <u>2.º nivel</u> sin gastar ranura.\n• <strong>3 cargas:</strong> descarga equivalente a <em>Rayo abrasador</em> (3 rayos de <u>2d6</u> de daño de fuego).\n\n<strong>Corruptibilidad</strong>\n• <u>+1 MC</u> por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: <u>+2 MC</u>.\n\n<strong>Identificación</strong>\n<em>Arcana CD 16</em>.\n\n<strong>Destrucción</strong>\nRomperlo con más de <u>30 puntos de daño contundente</u> lo neutraliza, liberando <u>4d6</u> de energía elemental (<em>CON CD 15, mitad con éxito</em>).\n\n<strong>Uso en mecanismos</strong>\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos."$text_ab91e77706d4cd95$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:bc5bf83aa5545f2bc45f837c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:cbefe528bbe7f909a82dcbc9' and md5(to_jsonb(t)::text)='30a979ac0bb83e7ec6194a72ee337bf7')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:cbefe528bbe7f909a82dcbc9';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f12668a680c49ae7$"Esta varita corta y ligeramente torcida tiene símbolos irregulares que parecen moverse cuando no se los observa. Al sostenerla emite un zumbido tenue, como un insecto atrapado en una linterna.\n\nComo acción, gasta 1 carga y elige una criatura que puedas ver a 30 pies o menos. Debe superar una salvación de Sabiduría CD 14. Si falla, queda fastidiada hasta el comienzo de tu siguiente turno y tiene desventaja en la primera salvación de Constitución que realice para mantener la concentración durante ese intervalo. Después de esa salvación termina la desventaja. Si no realiza ninguna, el efecto expira al comienzo de tu siguiente turno. Una salvación exitosa evita el efecto.\n\nLa varita no inflige daño ni rompe automáticamente la concentración, no impide acciones ni reacciones y no penaliza otras salvaciones, pruebas o ataques. El fastidio se manifiesta como suspiros, quejas o irritación; no es un estado oficial de 5e.\n\nTiene 3 cargas y recupera todas las cargas gastadas al amanecer. No recupera cargas por un descanso. No puede activarse sin cargas.\n\nNo puede destruirse por medios ordinarios. Su destrucción mediante magia o acontecimientos especiales se resuelve por el GM."$text_f12668a680c49ae7$::jsonb,true),'{features}',$text_0990364e2f52a9de$[{"id":"annoyance","kind":"action","name":"Provocar fastidio","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Como acción, gasta 1 carga y elige una criatura que puedas ver a 30 pies o menos. Debe superar una salvación de Sabiduría CD 14. Si falla, queda fastidiada hasta el comienzo de tu siguiente turno y tiene desventaja en la primera salvación de Constitución que realice para mantener la concentración durante ese intervalo. Después de esa salvación termina la desventaja. Si no realiza ninguna, el efecto expira al comienzo de tu siguiente turno. Una salvación exitosa evita el efecto.\n\nLa varita no inflige daño ni rompe automáticamente la concentración, no impide acciones ni reacciones y no penaliza otras salvaciones, pruebas o ataques. El fastidio se manifiesta como suspiros, quejas o irritación; no es un estado oficial de 5e.\n\nTiene 3 cargas y recupera todas las cargas gastadas al amanecer. No recupera cargas por un descanso. No puede activarse sin cargas.\n\nDuración: Hasta el comienzo de tu siguiente turno; la desventaja termina al aplicarse una vez..\n\nAlcance: 30 pies; criatura visible.\n\nCoste: 1 Cargas.","showInActions":true}]$text_0990364e2f52a9de$::jsonb,true),'{rules,definition,description}',$text_07897baa08380fd4$[{"id":"wand-flavor","text":"Esta varita corta y ligeramente torcida tiene símbolos irregulares que parecen moverse cuando no se los observa. Al sostenerla emite un zumbido tenue, como un insecto atrapado en una linterna.","type":"paragraph","section":"flavor","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"wand-rule","text":"Como acción, gasta 1 carga y elige una criatura que puedas ver a 30 pies o menos. Debe superar una salvación de Sabiduría CD 14. Si falla, queda fastidiada hasta el comienzo de tu siguiente turno y tiene desventaja en la primera salvación de Constitución que realice para mantener la concentración durante ese intervalo. Después de esa salvación termina la desventaja. Si no realiza ninguna, el efecto expira al comienzo de tu siguiente turno. Una salvación exitosa evita el efecto.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"wand-limits","text":"La varita no inflige daño ni rompe automáticamente la concentración, no impide acciones ni reacciones y no penaliza otras salvaciones, pruebas o ataques. El fastidio se manifiesta como suspiros, quejas o irritación; no es un estado oficial de 5e.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"wand-charges","text":"Tiene 3 cargas y recupera todas las cargas gastadas al amanecer. No recupera cargas por un descanso. No puede activarse sin cargas.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"wand-durability","text":"No puede destruirse por medios ordinarios. Su destrucción mediante magia o acontecimientos especiales se resuelve por el GM.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"}]$text_07897baa08380fd4$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_110a17cd0e6ef481$["wand-flavor","wand-rule","wand-limits","wand-charges","wand-durability"]$text_110a17cd0e6ef481$::jsonb?id),jsonb_build_array('wand-flavor')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:cbefe528bbe7f909a82dcbc9';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:da5aa681decf2561baece063' and md5(to_jsonb(t)::text)='48a316408138bff11facb7af145f3350')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:da5aa681decf2561baece063';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5a9e9ab74e4d27e0$"Esta túnica ligera está confeccionada con telas finas y flexibles, atravesadas por delicadas runas protectoras bordadas con hilo arcano casi imperceptible. Su diseño se atribuye al sabio Agati, quien sostenía que la defensa más perfecta no debía entorpecer ni el cuerpo ni la mente.\n\nMientras lleves puesta la túnica, tu Clase de Armadura aumenta en +3, envolviéndote en un campo protector sutil que desvía golpes y atenúa impactos sin recurrir a peso ni rigidez.\n\nLa túnica no se considera armadura y puede usarse sin interferir con el lanzamiento de conjuros, permitiendo que la energía mágica fluya con total libertad a través del portador."$text_5a9e9ab74e4d27e0$::jsonb,true),'{features}',$text_f6ab809ed8a351e6$[{"id":"agati-ac","kind":"passive","name":"Protección de Agati","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica ligera está confeccionada con telas finas y flexibles, atravesadas por delicadas runas protectoras bordadas con hilo arcano casi imperceptible. Su diseño se atribuye al sabio Agati, quien sostenía que la defensa más perfecta no debía entorpecer ni el cuerpo ni la mente.\n\nMientras lleves puesta la túnica, tu Clase de Armadura aumenta en +3, envolviéndote en un campo protector sutil que desvía golpes y atenúa impactos sin recurrir a peso ni rigidez.\n\nLa túnica no se considera armadura y puede usarse sin interferir con el lanzamiento de conjuros, permitiendo que la energía mágica fluya con total libertad a través del portador.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_f6ab809ed8a351e6$::jsonb,true),'{rules,definition,description}',$text_6bc6c02f7614387b$[{"id":"campaign-text-0","text":"Esta túnica ligera está confeccionada con telas finas y flexibles, atravesadas por delicadas runas protectoras bordadas con hilo arcano casi imperceptible. Su diseño se atribuye al sabio Agati, quien sostenía que la defensa más perfecta no debía entorpecer ni el cuerpo ni la mente.\n\nMientras lleves puesta la túnica, tu Clase de Armadura aumenta en +3, envolviéndote en un campo protector sutil que desvía golpes y atenúa impactos sin recurrir a peso ni rigidez.\n\nLa túnica no se considera armadura y puede usarse sin interferir con el lanzamiento de conjuros, permitiendo que la energía mágica fluya con total libertad a través del portador.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_6bc6c02f7614387b$::jsonb,true),'{rules,personalDescription}',$text_0884218dbccc8847$"Esta túnica ligera está confeccionada con telas finas y flexibles, atravesadas por delicadas runas protectoras bordadas con hilo arcano casi imperceptible. Su diseño se atribuye al sabio Agati, quien sostenía que la defensa más perfecta no debía entorpecer ni el cuerpo ni la mente.\n\nMientras lleves puesta la túnica, tu <u>Clase de Armadura aumenta en +3</u>, envolviéndote en un campo protector sutil que desvía golpes y atenúa impactos sin recurrir a peso ni rigidez.\n\nLa túnica <u>no se considera armadura</u> y puede usarse sin interferir con el lanzamiento de conjuros, permitiendo que la energía mágica fluya con total libertad a través del portador."$text_0884218dbccc8847$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:da5aa681decf2561baece063';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:f9a55f61d3ecdfdc16848447' and md5(to_jsonb(t)::text)='d4fb2cf4c853bfa82a277bab19f4d117')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:f9a55f61d3ecdfdc16848447';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_d7b793dae4787cd9$"Una esfera de tecnología aeloriana modificada por Draven a partir de un núcleo recuperado en un antiguo campamento de investigación. Un cristal luciente central permanece suspendido entre varios anillos metálicos móviles cubiertos de grabados resonantes.\n\nVinculación: Requiere vinculación por una criatura competente con Herramientas de Artífice o Herramientas de Tinkerer.\n\nCargas: El núcleo posee 3 cargas máximas. Recupera todas sus cargas durante un descanso largo si se inserta un fragmento de Cristal Luciente en su receptáculo interno. Sin cristal no recupera cargas.\n\nResonancia del Recuerdo (Verde): Consume 1 carga. Durante 10 minutos el usuario obtiene ventaja en pruebas de Investigación relacionadas con tecnología aeloriana y para localizar inscripciones, mecanismos o rastros mágicos ocultos.\n\nResonancia del Umbral (Azul): Consume 1 carga. Durante 1 minuto el usuario obtiene resistencia al daño por frío y ventaja en tiradas realizadas para resistir condiciones climáticas extremas.\n\nResonancia de la Revelación (Violeta): Consume 1 carga. Durante 1 minuto el núcleo puede interactuar con mecanismos aelorianos, activar dispositivos resonantes y abrir cerraduras diseñadas para responder a frecuencias lucientes.\n\nReconfiguración: Como acción, una criatura vinculada puede cambiar la resonancia activa realizando una prueba de Inteligencia utilizando Herramientas de Artífice CD 12. Si falla, la acción se pierde y la resonancia no cambia.\n\nDesgaste: Cada vez que las 3 cargas sean consumidas antes de completar un descanso largo, tira 1d20. Con un resultado de 1, el núcleo se vuelve inestable. Mientras permanezca inestable, no puede utilizar la Resonancia de la Revelación. Puede repararse durante un descanso largo utilizando materiales metálicos valorados en 25 po y un fragmento de Cristal Luciente.\n\nEstado actual: Se trata de un dispositivo experimental cuya verdadera capacidad aún no ha sido descubierta. Las ruinas aelorianas podrían revelar nuevas resonancias y mejoras permanentes.\n\nLas resonancias se activan con una acción y una carga; solo se mantiene un efecto de resonancia del núcleo a la vez. Reconfigurar sigue siendo una acción con prueba de Inteligencia y herramientas CD 12, sin coste de carga. No se descuenta automáticamente un cristal insertado para recargar: el texto exige insertarlo, pero no declara que se consuma. El GM confirma los materiales utilizados en una reparación."$text_d7b793dae4787cd9$::jsonb,true),'{features}',$text_febda13fcab69ca9$[{"id":"resonance-green","kind":"action","name":"Resonancia del Recuerdo (verde)","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Resonancia del Recuerdo (Verde): Consume 1 carga. Durante 10 minutos el usuario obtiene ventaja en pruebas de Investigación relacionadas con tecnología aeloriana y para localizar inscripciones, mecanismos o rastros mágicos ocultos.\n\nDuración: 10 minutos.\n\nCoste: 1 Cargas del núcleo.","showInActions":true},{"id":"resonance-blue","kind":"action","name":"Resonancia del Umbral (azul)","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Resonancia del Umbral (Azul): Consume 1 carga. Durante 1 minuto el usuario obtiene resistencia al daño por frío y ventaja en tiradas realizadas para resistir condiciones climáticas extremas.\n\nDuración: 1 minuto.\n\nCoste: 1 Cargas del núcleo.","showInActions":true},{"id":"resonance-violet","kind":"action","name":"Resonancia de la Revelación (violeta)","uses":null,"order":2,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Resonancia de la Revelación (Violeta): Consume 1 carga. Durante 1 minuto el núcleo puede interactuar con mecanismos aelorianos, activar dispositivos resonantes y abrir cerraduras diseñadas para responder a frecuencias lucientes.\n\nInteractuar con mecanismos aelorianos, activar dispositivos resonantes y abrir cerraduras que respondan a frecuencias lucientes.\n\nDuración: 1 minuto.\n\nCoste: 1 Cargas del núcleo.","showInActions":true}]$text_febda13fcab69ca9$::jsonb,true),'{rules,definition,description}',$text_8625ebade28c399e$[{"id":"campaign-text-0","text":"Una esfera de tecnología aeloriana modificada por Draven a partir de un núcleo recuperado en un antiguo campamento de investigación. Un cristal luciente central permanece suspendido entre varios anillos metálicos móviles cubiertos de grabados resonantes.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"campaign-text-1","text":"Vinculación: Requiere vinculación por una criatura competente con Herramientas de Artífice o Herramientas de Tinkerer.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"campaign-text-2","text":"Cargas: El núcleo posee 3 cargas máximas. Recupera todas sus cargas durante un descanso largo si se inserta un fragmento de Cristal Luciente en su receptáculo interno. Sin cristal no recupera cargas.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"campaign-text-3","text":"Resonancia del Recuerdo (Verde): Consume 1 carga. Durante 10 minutos el usuario obtiene ventaja en pruebas de Investigación relacionadas con tecnología aeloriana y para localizar inscripciones, mecanismos o rastros mágicos ocultos.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"campaign-text-4","text":"Resonancia del Umbral (Azul): Consume 1 carga. Durante 1 minuto el usuario obtiene resistencia al daño por frío y ventaja en tiradas realizadas para resistir condiciones climáticas extremas.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"campaign-text-5","text":"Resonancia de la Revelación (Violeta): Consume 1 carga. Durante 1 minuto el núcleo puede interactuar con mecanismos aelorianos, activar dispositivos resonantes y abrir cerraduras diseñadas para responder a frecuencias lucientes.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"campaign-text-6","text":"Reconfiguración: Como acción, una criatura vinculada puede cambiar la resonancia activa realizando una prueba de Inteligencia utilizando Herramientas de Artífice CD 12. Si falla, la acción se pierde y la resonancia no cambia.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"campaign-text-7","text":"Desgaste: Cada vez que las 3 cargas sean consumidas antes de completar un descanso largo, tira 1d20. Con un resultado de 1, el núcleo se vuelve inestable. Mientras permanezca inestable, no puede utilizar la Resonancia de la Revelación. Puede repararse durante un descanso largo utilizando materiales metálicos valorados en 25 po y un fragmento de Cristal Luciente.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"campaign-text-8","text":"Estado actual: Se trata de un dispositivo experimental cuya verdadera capacidad aún no ha sido descubierta. Las ruinas aelorianas podrían revelar nuevas resonancias y mejoras permanentes.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"},{"id":"operational-clarification","text":"Las resonancias se activan con una acción y una carga; solo se mantiene un efecto de resonancia del núcleo a la vez. Reconfigurar sigue siendo una acción con prueba de Inteligencia y herramientas CD 12, sin coste de carga. No se descuenta automáticamente un cristal insertado para recargar: el texto exige insertarlo, pero no declara que se consuma. El GM confirma los materiales utilizados en una reparación.","type":"paragraph","section":"rules","sourceIds":["ece-gm-campaign-resolution"],"provenance":"campaign"}]$text_8625ebade28c399e$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_42db12cbc6567d0a$["campaign-text-0","campaign-text-1","campaign-text-2","campaign-text-3","campaign-text-4","campaign-text-5","campaign-text-6","campaign-text-7","campaign-text-8","operational-clarification"]$text_42db12cbc6567d0a$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:f9a55f61d3ecdfdc16848447';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:fb36d9c23d740e8f2e5d2d26' and md5(to_jsonb(t)::text)='d65c4dc16993cbac525c4b3656c090b9')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:fb36d9c23d740e8f2e5d2d26';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_6b49dddd31357c12$"Este amuleto de diseño sobrio porta un símbolo arcano grabado con precisión geométrica, pensado no para amplificar el poder bruto, sino para ordenar y clarificar el pensamiento mágico. Es un instrumento común entre magos eruditos, investigadores arcanos y aprendices avanzados.\n\nMientras lo llevas puesto, obtienes un bonificador de +2 a las pruebas de Arcana, como si el amuleto ayudara a estabilizar conceptos, recordar fórmulas y reconocer patrones mágicos complejos.\n\nEl amuleto no emite energía perceptible ni interfiere con otros efectos mágicos, funcionando como una ayuda constante y silenciosa para la mente entrenada."$text_6b49dddd31357c12$::jsonb,true),'{features}',$text_3c1f73393e5bab6f$[{"id":"arcana-bonus","kind":"passive","name":"Ayuda arcana","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este amuleto de diseño sobrio porta un símbolo arcano grabado con precisión geométrica, pensado no para amplificar el poder bruto, sino para ordenar y clarificar el pensamiento mágico. Es un instrumento común entre magos eruditos, investigadores arcanos y aprendices avanzados.\n\nMientras lo llevas puesto, obtienes un bonificador de +2 a las pruebas de Arcana, como si el amuleto ayudara a estabilizar conceptos, recordar fórmulas y reconocer patrones mágicos complejos.\n\nEl amuleto no emite energía perceptible ni interfiere con otros efectos mágicos, funcionando como una ayuda constante y silenciosa para la mente entrenada.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_3c1f73393e5bab6f$::jsonb,true),'{rules,definition,description}',$text_5063d41773cd834d$[{"id":"campaign-text-0","text":"Este amuleto de diseño sobrio porta un símbolo arcano grabado con precisión geométrica, pensado no para amplificar el poder bruto, sino para ordenar y clarificar el pensamiento mágico. Es un instrumento común entre magos eruditos, investigadores arcanos y aprendices avanzados.\n\nMientras lo llevas puesto, obtienes un bonificador de +2 a las pruebas de Arcana, como si el amuleto ayudara a estabilizar conceptos, recordar fórmulas y reconocer patrones mágicos complejos.\n\nEl amuleto no emite energía perceptible ni interfiere con otros efectos mágicos, funcionando como una ayuda constante y silenciosa para la mente entrenada.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_5063d41773cd834d$::jsonb,true),'{rules,personalDescription}',$text_5ff2a080de8de87d$"Este amuleto de diseño sobrio porta un símbolo arcano grabado con precisión geométrica, pensado no para amplificar el poder bruto, sino para ordenar y clarificar el pensamiento mágico. Es un instrumento común entre magos eruditos, investigadores arcanos y aprendices avanzados.\n\nMientras lo llevas puesto, obtienes un <u>bonificador de +2 a las pruebas de Arcana</u>, como si el amuleto ayudara a estabilizar conceptos, recordar fórmulas y reconocer patrones mágicos complejos.\n\nEl amuleto no emite energía perceptible ni interfiere con otros efectos mágicos, funcionando como una ayuda constante y silenciosa para la mente entrenada."$text_5ff2a080de8de87d$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:fb36d9c23d740e8f2e5d2d26';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:ffa6888520af7c400c801946' and md5(to_jsonb(t)::text)='877ad25f206f5d1db04b1e356a3206d3')then raise exception 'ITEM_TEXT_CONFLICT:ece:imported:equipment:legacy:ffa6888520af7c400c801946';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_5a65b9a179ca78e9$[{"id":"haste","kind":"action","name":"Acelerar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Este bastón de madera clara está gastado por el uso y marcado por antiguas muescas, recuerdo de caminos recorridos con prisa y combates improvisados. \n Perteneció a Isadora, una exploradora que murió intentando advertir a los protagonistas sobre la conspiración de los contrabandistas en Valverde del Río. \n El bastón conserva un encantamiento residual ligado al movimiento y la urgencia: \n una vez por descanso largo, su portador puede conjurar *Acelerar*, como si el arma respondiera al impulso desesperado de huir, alcanzar o llegar a tiempo.\n\nDuración: Hasta 1 minuto.\n\nConcentración: sí.\n\nCoste: 1 acelerar.","showInActions":true}]$text_5a65b9a179ca78e9$::jsonb,true),'{rules,personalDescription}',$text_69c28c2bd7881605$"Este bastón de madera clara está gastado por el uso y marcado por antiguas muescas, recuerdo de caminos recorridos con prisa y combates improvisados. \n Perteneció a Isadora, una exploradora que murió intentando advertir a los protagonistas sobre la conspiración de los contrabandistas en Valverde del Río. \n El bastón conserva un encantamiento residual ligado al movimiento y la urgencia: \n una vez por descanso largo, su portador puede conjurar *Acelerar*, como si el arma respondiera al impulso desesperado de huir, alcanzar o llegar a tiempo."$text_69c28c2bd7881605$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='imported:equipment:legacy:ffa6888520af7c400c801946';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:01213a8f63ace3ea64f5e250' and md5(to_jsonb(t)::text)='0ecbf1c87e0875fa525b32600250dd6c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:01213a8f63ace3ea64f5e250';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_360c1f49b3517576$[{"id":"official-base-table","rows":[["Jabalina","5 pp","2 lb","1d6 perforante","+0","Arrojadiza","30/120"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_360c1f49b3517576$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_64a098dd9f8d2e39$["official-base-table","property-thrown","family-rule"]$text_64a098dd9f8d2e39$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:01213a8f63ace3ea64f5e250';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0157632c42b2f0ccb59090f8' and md5(to_jsonb(t)::text)='2f2df824e1cc3473f07044508bf707f3')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:0157632c42b2f0ccb59090f8';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_6124846e52dfb250$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica\nEspadón de lengua de fuego · 50 po (solo objeto mundano base; no es el precio de la variante mágica) · 6 lb · 2d6 cortante · Pesada, A dos manos · +0\n\nPuedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_6124846e52dfb250$::jsonb,true),'{features}',$text_010aa9920d571615$[{"id":"flaming-toggle","kind":"bonus-action","name":"Encender o apagar la hoja","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nPronuncia la palabra de activación como acción adicional para encender o apagar la hoja. Encendida, emite luz brillante a 40 pies y tenue otros 40 pies. Las llamas se apagan al soltarla o envainarla.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":true},{"id":"flaming-hit","kind":"other","name":"Daño con la hoja encendida","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_010aa9920d571615$::jsonb,true),'{rules,definition,description}',$text_73f0bf892b94aec1$[{"id":"official-table","rows":[["Espadón de lengua de fuego","50 po (solo objeto mundano base; no es el precio de la variante mágica)","6 lb","2d6 cortante","Pesada, A dos manos","+0"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-enchantment-0","text":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_73f0bf892b94aec1$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b62022ae7cf860f9$["official-table","official-enchantment-0"]$text_b62022ae7cf860f9$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0157632c42b2f0ccb59090f8';
