if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:05dc4be45345df58030acae8' and md5(to_jsonb(t)::text)='afab7c64765afab362cdf9bd919f7b5b')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:05dc4be45345df58030acae8';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_9d38205f36525cc3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para mostrar el cetro y exigir obediencia a todas las criaturas de tu elección que puedas ver a 36 m o menos de ti. Cada objetivo deberá superar una tirada de salvación de Sabiduría con CD 15 o quedará hechizado por ti durante 8 horas. Mientras estén hechizadas de esta manera, las criaturas te considerarán su líder de confianza. Si tus compañeros o tú les causáis daño o si se les ordena llevar a cabo algo contrario a su naturaleza, los objetivos dejarán de estar hechizados de esta forma. El cetro no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_9d38205f36525cc3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:05dc4be45345df58030acae8';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:079105286daecce94d961d55' and md5(to_jsonb(t)::text)='273466ff3705e25678c9fe7bb070fdb8')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:079105286daecce94d961d55';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_b941c3ef7d1ae2c4$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica\nAlabarda feroz · 20 po (solo objeto mundano base; no es el precio de la variante mágica) · 6 lb · 1d10 cortante · Pesada, Gran alcance, A dos manos · +0\n\nCuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_b941c3ef7d1ae2c4$::jsonb,true),'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_c07bdca3cc773c73$[{"id":"official-table","rows":[["Alabarda feroz","20 po (solo objeto mundano base; no es el precio de la variante mágica)","6 lb","1d10 cortante","Pesada, Gran alcance, A dos manos","+0"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"vicious-2014","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_c07bdca3cc773c73$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6851a11da4c0ecd0$["official-table","vicious-2014"]$text_6851a11da4c0ecd0$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:079105286daecce94d961d55';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0896a39342fdfdeba982f162' and md5(to_jsonb(t)::text)='9af09a8b67c7f8bad070b4c170b06af7')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:0896a39342fdfdeba982f162';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_879da69c05a059b2$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Si sostienes este medallón con forma de escarabajo en la mano durante 1 asalto, aparecerá una inscripción en su superficie que revelará su naturaleza mágica. Proporciona dos beneficios mientras lo lleves encima: • Tienes ventaja en las tiradas de salvación contra conjuros. • El escarabajo tiene 12 cargas. Si fallas una tirada de salvación contra un conjuro de nigromancia o un efecto dañino de una criatura muerta viviente, podrás utilizar tu reacción y emplear 1 carga para superar la tirada de salvación. El escarabajo se convertirá en polvo y se destruirá cuando se haya empleado la última carga.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_879da69c05a059b2$::jsonb,true),'{rules,personalDescription}',$text_954f0f0e2298cf4c$"Si sostienes este medallón con forma de escarabajo en tu mano durante 1 asalto aparece una inscripción en su superficie, revelando su naturaleza mágica. Proporciona dos beneficios mientras lo lleves contigo:\n\nTienes ventaja en las tiradas de salvación contra conjuros.\n\nEl escarabajo posee 12 cargas. Si fallas una tirada de salvación contra un conjuro nigromántico o efecto dañino de una criatura muerta viviente, puedes usar tu reacción para gastar 1 carga y convertir la tirada fallida en una tirada con éxito. El escarabajo se convierte en polvo y queda destruido cuando se utiliza su última carga."$text_954f0f0e2298cf4c$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0896a39342fdfdeba982f162';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:08aeefad60648a37018c0624' and md5(to_jsonb(t)::text)='189f65b096c74bc2aec05ebb841b4bfe')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:08aeefad60648a37018c0624';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3d20682e3808f6a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para soplar este cuerno. Como respuesta, varios espíritus guerreros del Valhalla aparecerán a 18 m o menos de ti. Utilizan el perfil del berserker. Regresarán al Valhalla después de 1 hora o cuando sus puntos de golpe se reduzcan a 0. Una vez que utilices el cuerno, no podrás volver a usarlo hasta que hayan pasado 7 días.\n\nSe conoce la existencia de cuatro tipos de cuerno del Valhalla, cada uno hecho de un metal distinto. El tipo de cuerno determina cuántos berserkers responden a su llamada, así como el requisito para utilizarlo. Tu GM elige el tipo de cuerno o lo determina al azar.\n\n01–40 · Plata · 2d4 + 2 · Ninguno\n41–75 · Oropel · 3d4 + 3 · Competencia con todas las armas sencillas\n76–90 · Bronce · 4d4 + 4 · Competencia con todas las armaduras medias\n91–00 · Hierro · 5d4 + 5 · Competencia con todas las armas marciales\n\nSi soplas el cuerno sin cumplir su requisito, los berserkers invocados te atacarán. Si cumples el requisito, serán amistosos contigo y tus compañeros, y seguirán tus órdenes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3d20682e3808f6a0$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:08aeefad60648a37018c0624';
