and kind='equipment' and content_key='official:equipment:es:0b2e37f3e48893c6a5286c48';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0ba1a16b9c6d2e8701b1e58b' and md5(to_jsonb(t)::text)='9ad656402e0b5cca25498c0bb25e53db')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:0ba1a16b9c6d2e8701b1e58b';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_0321897cd078f611$[{"id":"official-base-table","rows":[["Ballesta de mano","75 po","3 lb","1d6 perforante","+0","Munición, Ligera, Recarga","30/120"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-ammunition","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-loading","text":"Recarga. Debido al tiempo que requiere recargar un arma con esta propiedad, cuando utilices una acción, acción adicional o reacción para atacar con ella, solo podrás disparar una unidad de munición, incluso aunque normalmente pudieras hacer más de un ataque.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_0321897cd078f611$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_e2cd7cad5d764c5f$["official-base-table","property-ammunition","property-light","property-loading","family-rule"]$text_e2cd7cad5d764c5f$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0ba1a16b9c6d2e8701b1e58b';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0cba9b4d9ef522fe32934799' and md5(to_jsonb(t)::text)='6e701280690f58556563f722927bbdf4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:0cba9b4d9ef522fe32934799';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_249d9877e6e0199e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, tu puntuación de Fuerza cambiará durante 1 hora. El tipo de gigante determina la puntuación (consulta la tabla más adelante). La poción no tendrá ningún efecto si tu Fuerza es igual o superior a esa puntuación.\n\nEn el líquido transparente de la poción flota un trozo de uña de un gigante del tipo correspondiente. La poción de fuerza de gigante de escarcha y la poción de fuerza de gigante de piedra tienen el mismo efecto.\n\nGigante de las colinas · 21 · Infrecuente\nGigante de escarcha/piedra · 23 · Rara\nGigante de fuego · 25 · Rara\nGigante de las nubes · 27 · Muy rara\nGigante de las tormentas · 29 · Legendaria\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_249d9877e6e0199e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0cba9b4d9ef522fe32934799';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0cfae63a1a143c1604e3deb0' and md5(to_jsonb(t)::text)='63e2d80c79f9c4c0e2554639a8268cde')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:0cfae63a1a143c1604e3deb0';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_1100fe11a92e9703$"Objeto · Precio base · Peso\nHerramientas de manitas · 50 po · 10 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_1100fe11a92e9703$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_0e984290eec89789$[{"id":"official-table","rows":[["Herramientas de manitas","50 po","10 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_0e984290eec89789$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0cfae63a1a143c1604e3deb0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0f35540ad5761cc8b53de256' and md5(to_jsonb(t)::text)='267943b4abbd5fcfcb80a036458c7232')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:0f35540ad5761cc8b53de256';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_b0fdb5e9b42a7c29$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b0fdb5e9b42a7c29$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0f35540ad5761cc8b53de256';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0fdb2edd8391f7440a662f31' and md5(to_jsonb(t)::text)='9b3e3f70b9fd166254cc40f1a799b648')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:0fdb2edd8391f7440a662f31';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_eaccb461f4441898$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer. Mientras lo lleves puesto, podrás utilizar una acción para gastar 1 de sus cargas en lanzar uno de los siguientes conjuros: • Encantar animal (CD de salvación 13). • Hablar con los animales. • Terror (CD de salvación 13), que solo puede hacer objetivo a bestias que tengan una Inteligencia de 3 o menos.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_eaccb461f4441898$::jsonb,true),'{rules,personalDescription}',$text_2cd74815406ee132$"Este anillo tiene 3 cargas y recupera 1d3 de las cargas gastadas diariamente al amanecer. Mientras llevas puesto el anillo, puedes usar una acción para gastar 1 de sus cargas y lanzar uno de los siguientes conjuros:\n\n-Amistad animal (salvacion DC 13 \n-Miedo (salvacion DC 13),apuntando solo a bestias que tengan una Inteligencia de 3 o menor \n-Hablar con animales"$text_2cd74815406ee132$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:0fdb2edd8391f7440a662f31';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:11d881cebe78bd3b6034c457' and md5(to_jsonb(t)::text)='4331be8ae71bb9b652db37247a6b2d0c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:11d881cebe78bd3b6034c457';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3b1106888529a711$[{"id":"flaming-toggle","kind":"bonus-action","name":"Encender o apagar la hoja","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nPronunciar la palabra de activación como acción adicional. Emite luz brillante a 40 pies y tenue otros 40 pies; se apaga al soltarla, envainarla o volver a usar la palabra como acción adicional.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":true},{"id":"flaming-hit","kind":"other","name":"Daño con la hoja encendida","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_3b1106888529a711$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:11d881cebe78bd3b6034c457';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 1 as batch,27 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;